package com.yonlab.vision;
import android.content.Context;
import android.os.Build;
import java.util.*;
/** Executable model/engine registry. CPU thread counts are settings, not model entries. */
public final class OneModels {
 private OneModels(){}
 public static final class Entry {public final String id,title,summary;public final boolean recommended;public Entry(String id,String title,String summary,boolean recommended){this.id=id;this.title=title;this.summary=summary;this.recommended=recommended;}}
 public static List<Entry> list(Context c,String feature){String f=OneModelPolicy.canonicalFeature(feature);if("speech".equals(f))return speech(c);List<Entry> out=new ArrayList<>();String first=OneModelPolicy.defaultId(f,Build.VERSION.SDK_INT);for(String id:OneModelPolicy.models(f,Build.VERSION.SDK_INT))out.add(new Entry(id,label(id),description(id),id.equals(first)));return Collections.unmodifiableList(out);}
 public static String selected(Context c,String feature){feature=OneModelPolicy.canonicalFeature(feature);if("speech".equals(feature)){try{return (String)Class.forName("com.yonlab.offlinevoice.VoiceModels").getMethod("selected",Context.class).invoke(null,c);}catch(ReflectiveOperationException|LinkageError e){return "";}}List<Entry> entries=list(c,feature);if(entries.isEmpty())return "";String saved=c.getSharedPreferences("YOnOneModels",0).getString(feature,"");for(Entry e:entries)if(e.id.equals(saved))return saved;return entries.get(0).id;}
 public static void select(Context c,String feature,String id){feature=OneModelPolicy.canonicalFeature(feature);boolean found=false;for(Entry e:list(c,feature))if(e.id.equals(id))found=true;if(!found)throw new IllegalArgumentException("이 기능에 맞는 모델을 선택하세요");if("speech".equals(feature)){try{Class.forName("com.yonlab.offlinevoice.VoiceModels").getMethod("select",Context.class,String.class).invoke(null,c,id);return;}catch(ReflectiveOperationException|LinkageError e){throw new IllegalArgumentException("음성 모델을 선택할 수 없습니다",e);}}c.getSharedPreferences("YOnOneModels",0).edit().putString(feature,id).apply();}
 public static String title(Context c,String feature,String id){for(Entry e:list(c,feature))if(e.id.equals(id))return e.title;throw new IllegalArgumentException("모델을 확인하세요");}
 public static String resolve(Context c,String feature,String requested){String f=OneModelPolicy.canonicalFeature(feature);String id=requested==null||requested.isEmpty()?selected(c,f):requested;for(Entry e:list(c,f))if(e.id.equals(id))return id;throw new IllegalArgumentException("이 기능에 맞는 모델을 선택하세요");}
 public static List<Entry> list(Context c,String feature,String group){if(!"speech".equals(feature)){List<Entry> base=list(c,feature);if(!"ocr".equals(feature)&&!"document".equals(feature))return base;String first=OneModelPolicy.defaultId(feature,Build.VERSION.SDK_INT,group);List<Entry> ordered=new ArrayList<>();for(Entry e:base)if(e.id.equals(first))ordered.add(new Entry(e.id,e.title,e.summary,true));for(Entry e:base)if(!e.id.equals(first))ordered.add(new Entry(e.id,e.title,e.summary,false));return Collections.unmodifiableList(ordered);}try{Object values=Class.forName("com.yonlab.offlinevoice.VoiceModels").getMethod("list",Context.class,String.class).invoke(null,c,group);return voiceEntries(values);}catch(ReflectiveOperationException|LinkageError e){return Collections.emptyList();}}
 public static String selected(Context c,String feature,String group){if(!"speech".equals(feature)){if(!"ocr".equals(feature)&&!"document".equals(feature))return selected(c,feature);String key=feature+"@"+("GO".equals(group)?"GO":"KO".equals(group)?"KO":"ALL"),saved=c.getSharedPreferences("YOnOneModels",0).getString(key,"");for(Entry e:list(c,feature,group))if(e.id.equals(saved))return saved;return OneModelPolicy.defaultId(feature,Build.VERSION.SDK_INT,group);}try{return (String)Class.forName("com.yonlab.offlinevoice.VoiceModels").getMethod("selected",Context.class,String.class).invoke(null,c,group);}catch(ReflectiveOperationException|LinkageError e){return "";}}
 public static void select(Context c,String feature,String id,String group){if("speech".equals(feature)){try{Class.forName("com.yonlab.offlinevoice.VoiceModels").getMethod("select",Context.class,String.class,String.class).invoke(null,c,id,group);return;}catch(ReflectiveOperationException|LinkageError e){throw new IllegalArgumentException("음성 모델을 선택할 수 없습니다",e);}}select(c,feature,id);if("ocr".equals(feature)||"document".equals(feature))c.getSharedPreferences("YOnOneModels",0).edit().putString(feature+"@"+("GO".equals(group)?"GO":"KO".equals(group)?"KO":"ALL"),id).apply();}
 private static List<Entry> voiceEntries(Object result)throws ReflectiveOperationException{List<Entry> out=new ArrayList<>();for(Object e:(Iterable<?>)result){Class<?> k=e.getClass();out.add(new Entry((String)k.getField("id").get(e),(String)k.getField("title").get(e),(String)k.getField("summary").get(e),k.getField("recommended").getBoolean(e)));}return Collections.unmodifiableList(out);}
 private static String label(String id){String added=ModelPlusPolicy.label(id);if(added!=null)return added;String extra=ExpansionModels.label(id);if(extra!=null)return extra;switch(id){case "ssd-mobilenet-v1":return "SSD MobileNet";case "yolo26n":return "YOLO26n";case "mobilenet-v4-fp32":return "MobileNetV4 Small FP32";case "mobilenet-v2-2022":return "MobileNetV2 FP32";case "pphumanseg-2023":return "PPHumanSeg";case "yolo26n-seg":return "YOLO26n Seg";case "mlkit-sface-2023":return "ML Kit · YuNet · SFace";case "yunet-2026-sface":return "YuNet 2026 · SFace";case "mlkit-face-contours":return "ML Kit Face Contours";case "mlkit-pose":return "ML Kit Pose";case "mlkit-pose-accurate":return "ML Kit Pose Accurate";case "mlkit-ocr-ko":return "ML Kit Korean OCR";case "mlkit-ocr-latin":return "ML Kit Latin OCR";case "zxing-qr":return "ZXing QR · Barcode";case "android-media":return "Android Media";default:return id;}}
 private static String description(String id){String added=ModelPlusPolicy.description(id);if(added!=null)return added;String extra=ExpansionModels.description(id);if(extra!=null)return extra;switch(id){case "ssd-mobilenet-v1":return "COCO 객체 탐지 · 빠른 응답 대안";case "yolo26n":return "COCO 80종 · ONNX CPU · AGPL-3.0";case "mobilenet-v4-fp32":return "ImageNet 1,000종 · FP32 ONNX 비교 모델";case "mobilenet-v2-2022":return "ImageNet 1,000종 · OpenCV Zoo 2022 비교 기준선";case "pphumanseg-2023":return "사람과 배경을 분리하는 2023 기준선";case "yolo26n-seg":return "객체별 마스크 · ONNX CPU · AGPL-3.0";case "yunet-2026-sface":return "동적 shape 재출력 · 기존 SFace128D 등록과 연결";case "mlkit-sface-2023":return "얼굴 관측·SFace128D · 기본 등록 모델";case "mlkit-face-contours":return "눈·고개·입 윤곽 관측";case "mlkit-pose":return "사진 자세 지점 · 기본 모델";case "mlkit-pose-accurate":return "사진 자세 지점 · 별도 Accurate 가중치";case "mlkit-ocr-ko":return "한국어 문서 읽기";case "mlkit-ocr-latin":return "영어·라틴 문자 문서 읽기";case "zxing-qr":return "QR·바코드 해석과 QR 생성 엔진";case "android-media":return "사진·영상 재생 엔진 · AI 모델 아님";default:return "";}}
 private static List<Entry> speech(Context c){try{Class<?> type=Class.forName("com.yonlab.offlinevoice.VoiceModels");Object result=type.getMethod("list",Context.class).invoke(null,c);List<Entry> out=new ArrayList<>();for(Object e:(Iterable<?>)result){Class<?> k=e.getClass();out.add(new Entry((String)k.getField("id").get(e),(String)k.getField("title").get(e),(String)k.getField("summary").get(e),k.getField("recommended").getBoolean(e)));}return Collections.unmodifiableList(out);}catch(ReflectiveOperationException|LinkageError e){return Collections.emptyList();}}
}
